	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		TrainingRun
	 */
		public TrainingRun createTrainingRun( CreateTrainingRunCommand command ) {

		TrainingRun entity = new TrainingRun();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setTrainingRunId( command.getTrainingRunId() );
            entity.setRunLabel( command.getRunLabel() );
            entity.setStartedAt( command.getStartedAt() );
            entity.setCompletedAt( command.getCompletedAt() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of TrainingRun {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateTrainingRunCommand
	 * @return		TrainingRun
	 */
	public TrainingRun updateTrainingRun( UpdateTrainingRunCommand command ) {

		TrainingRun entity = new TrainingRun();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setTrainingRunId( command.getTrainingRunId() );
            entity.setRunLabel( command.getRunLabel() );
            entity.setStartedAt( command.getStartedAt() );
            entity.setCompletedAt( command.getCompletedAt() );
            entity.setExperiment( command.getExperiment() );
            entity.setModelVersion( command.getModelVersion() );
            entity.setInputDatasets( command.getInputDatasets() );
            entity.setFeatures( command.getFeatures() );
            entity.setRunMetrics( command.getRunMetrics() );
            entity.setRunParameters( command.getRunParameters() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of TrainingRun {0} ", entity.toString() );

		return entity;
	}

