	/**
	 * Method to retrieve the TrainingRun via TrainingRunFetchOneSummary
	 * @param 	summary TrainingRunFetchOneSummary
	 * @return 	TrainingRunFetchOneResponse
	 */
	public TrainingRun getTrainingRun( TrainingRunFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "TrainingRunFetchOneSummary arg cannot be null" );

		TrainingRun entity = null;
		UUID id = summary.getTrainingRunId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a TrainingRun using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


